package com.fream.back.domain.m99.service.query;

import com.fream.back.domain.m99.dto.Xtw92ResponseDto;
import com.fream.back.domain.m99.dto.Xxn12Dto;
import com.fream.back.domain.m99.entity.Xtw92;
import com.fream.back.domain.m99.exception.Xzj75Exception;
import com.fream.back.domain.m99.exception.Xqx49Exception;
import com.fream.back.domain.m99.exception.Xsb40Exception;
import com.fream.back.domain.m99.repository.Xtw92Repository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;




@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
@Slf4j
public class Xtw92QueryService {

    private final Xtw92Repository orderBidRepository;








    public Optional<Xtw92> findById(Long id) {
        if (id == null) {
            throw new Xzj75Exception("주문 입찰 ID가 없습니다.");
        }
        return orderBidRepository.findById(id);
    }








    public Optional<Xtw92> findByOrderId(Long orderId) {
        if (orderId == null) {
            throw new Xzj75Exception("주문 ID가 없습니다.");
        }
        return orderBidRepository.findByOrderId(orderId);
    }












    public Page<Xtw92ResponseDto> getOrderBids(String email, String bidStatus, String orderStatus, Pageable pageable) {
        validateEmail(email);

        try {
            return orderBidRepository.findOrderBidsByFilters(email, bidStatus, orderStatus, pageable);
        } catch (Exception e) {
            log.error("주문 입찰 목록 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new Xzj75Exception("주문 입찰 목록 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }









    public Xxn12Dto getOrderBidStatusCounts(String email) {
        validateEmail(email);

        try {
            return orderBidRepository.countOrderBidsByStatus(email);
        } catch (Exception e) {
            log.error("주문 입찰 상태별 개수 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new Xzj75Exception("주문 입찰 상태별 개수 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }










    public Optional<Xtw92ResponseDto> getOrderBidDetail(Long orderBidId, String email) {
        if (orderBidId == null) {
            throw new Xzj75Exception("주문 입찰 ID가 없습니다.");
        }

        validateEmail(email);

        try {
            Xtw92ResponseDto responseDto = orderBidRepository.findOrderBidById(orderBidId, email);
            return Optional.ofNullable(responseDto);
        } catch (Exception e) {
            log.error("주문 입찰 상세 정보 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new Xzj75Exception("주문 입찰 상세 정보 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }







    private void validateEmail(String email) {
        if (email == null || email.trim().isEmpty()) {
            throw new Xqx49Exception("사용자 이메일이 없습니다.");
        }
    }
}package com.fream.back.domain.m99.repository;

import com.fream.back.domain.m99.dto.Xtw92ResponseDto;
import com.fream.back.domain.m99.dto.Xxn12Dto;
import com.fream.back.domain.m99.entity.Xkh73Status;
import com.fream.back.domain.m99.entity.QXhq12;
import com.fream.back.domain.m99.entity.QXtw92;
import com.fream.back.domain.m30.entity.QXnr50;
import com.fream.back.domain.m30.entity.QXvm17;
import com.fream.back.domain.m30.entity.QXdt35;
import com.fream.back.domain.m30.entity.QXcc44;
import com.fream.back.domain.m45.entity.QXfr60;
import com.fream.back.domain.m22.entity.QXjm45;
import com.querydsl.core.BooleanBuilder;
import com.querydsl.core.Tuple;
import com.querydsl.core.types.Projections;
import com.querydsl.jpa.impl.JPAQueryFactory;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;
import org.springframework.util.StringUtils;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;




@Repository
@RequiredArgsConstructor
public class Xtw92RepositoryImpl implements Xtw92RepositoryCustom {
    private final JPAQueryFactory queryFactory;

    @Override
    public Page<Xtw92ResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
        QXtw92 orderBid = QXtw92.xtw92;
        QXhq12 order = QXhq12.xhq12;
        QXcc44 productSize = QXcc44.xcc44;
        QXvm17 productColor = QXvm17.xvm17;
        QXnr50 product = QXnr50.xnr50;
        QXdt35 productImage = QXdt35.xdt35;
        QXfr60 orderShipment = QXfr60.xfr60;
        QXjm45 user = QXjm45.xjm45;


        BooleanBuilder whereBuilder = new BooleanBuilder();


        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
        }


        if (StringUtils.hasText(bidStatus)) {
            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
        }


        if (StringUtils.hasText(orderStatus)) {
            whereBuilder.and(order.status.stringValue().eq(orderStatus));
        }


        List<Xtw92ResponseDto> content = queryFactory
                .select(Projections.constructor(
                        Xtw92ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(whereBuilder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory
                .select(orderBid.id.count())
                .from(orderBid)
                .join(orderBid.user, user)
                .leftJoin(orderBid.order, order)
                .where(whereBuilder)
                .fetchOne();

        return new PageImpl<>(content, pageable, total != null ? total : 0L);
    }

    @Override
    public Xxn12Dto countOrderBidsByStatus(String email) {
        QXtw92 orderBid = QXtw92.xtw92;


        Long pendingCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xkh73Status.PENDING)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long matchedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xkh73Status.MATCHED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long cancelledOrCompletedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.in(
                                Xkh73Status.CANCELLED, Xkh73Status.COMPLETED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        pendingCount = pendingCount != null ? pendingCount : 0L;
        matchedCount = matchedCount != null ? matchedCount : 0L;
        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;

        return new Xxn12Dto(pendingCount, matchedCount, cancelledOrCompletedCount);
    }

    @Override
    public Xtw92ResponseDto findOrderBidById(Long orderBidId, String email) {
        QXtw92 orderBid = QXtw92.xtw92;
        QXhq12 order = QXhq12.xhq12;
        QXcc44 productSize = QXcc44.xcc44;
        QXvm17 productColor = QXvm17.xvm17;
        QXnr50 product = QXnr50.xnr50;
        QXdt35 productImage = QXdt35.xdt35;
        QXfr60 orderShipment = QXfr60.xfr60;
        QXjm45 user = QXjm45.xjm45;

        return queryFactory
                .select(Projections.constructor(
                        Xtw92ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(
                        orderBid.id.eq(orderBidId),
                        orderBid.user.email.eq(email)
                )
                .fetchOne();
    }

    @Override
    public Map<Long, Long> tradeCountByColorIds(List<Long> colorIds) {
        if (colorIds == null || colorIds.isEmpty()) {
            return Collections.emptyMap();
        }

        QXtw92 orderBid = QXtw92.xtw92;
        QXcc44 productSize = QXcc44.xcc44;

        List<Tuple> results = queryFactory.select(
                        productSize.productColor.id,
                        orderBid.id.count()
                )
                .from(orderBid)
                .join(orderBid.productSize, productSize)
                .where(
                        productSize.productColor.id.in(colorIds),
                        orderBid.status.eq(Xkh73Status.COMPLETED)
                )
                .groupBy(productSize.productColor.id)
                .fetch();

        return results.stream()
                .collect(Collectors.toMap(
                        t -> t.get(productSize.productColor.id),
                        t -> t.get(orderBid.id.count())
                ));
    }
}

